// The Pillory: shared behavior for the app screens.
// - Global search (dropdown on every tab, full results on /search/)
// - Scope filter on /issues/ (All / County / State / Federal)
// - Tabs on rep profiles (#overview, #promises, #votes, #issues)
// The search data comes from assets/search-index.js, generated by tools/build.py.

(function () {
  "use strict";

  var INDEX = window.PILLORY_INDEX || [];
  var DROPDOWN_LIMIT = 8;

  function norm(s) {
    return String(s || "").toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "");
  }

  function search(query) {
    var tokens = norm(query).split(/\s+/).filter(Boolean);
    if (!tokens.length) return [];
    return INDEX.filter(function (item) {
      var hay = norm([item.type, item.title, item.sub, item.k].join(" "));
      return tokens.every(function (t) { return hay.indexOf(t) !== -1; });
    });
  }

  function el(tag, cls, text) {
    var node = document.createElement(tag);
    if (cls) node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  }

  function resultLink(item) {
    var a = el("a", "search-result");
    a.href = item.url;
    a.appendChild(el("span", "search-result-type", item.type));
    a.appendChild(el("span", "search-result-title", item.title));
    if (item.sub) a.appendChild(el("span", "search-result-sub", item.sub));
    return a;
  }

  function searchUrl(q) {
    return "/search/?q=" + encodeURIComponent(q);
  }

  // Dropdown results under every search bar.
  document.querySelectorAll("form.search").forEach(function (form) {
    var input = form.querySelector("input");
    var box = form.querySelector(".search-results");

    function close() {
      box.hidden = true;
      input.setAttribute("aria-expanded", "false");
    }

    function render() {
      var q = input.value.trim();
      box.textContent = "";
      if (!q || document.getElementById("search-page-results")) return close();
      var results = search(q);
      results.slice(0, DROPDOWN_LIMIT).forEach(function (item) { box.appendChild(resultLink(item)); });
      if (!results.length) box.appendChild(el("p", "search-empty", "No matches in the sample data."));
      if (results.length > DROPDOWN_LIMIT) {
        var all = el("a", "search-all", "See all " + results.length + " results");
        all.href = searchUrl(q);
        box.appendChild(all);
      }
      box.hidden = false;
      input.setAttribute("aria-expanded", "true");
    }

    input.addEventListener("input", render);
    input.addEventListener("focus", render);
    form.addEventListener("keydown", function (e) {
      var links = Array.prototype.slice.call(box.querySelectorAll("a"));
      var i = links.indexOf(document.activeElement);
      if (e.key === "Escape") {
        close();
        input.focus();
      } else if (e.key === "ArrowDown" && links.length) {
        e.preventDefault();
        links[Math.min(i + 1, links.length - 1)].focus();
      } else if (e.key === "ArrowUp" && i !== -1) {
        e.preventDefault();
        (i === 0 ? input : links[i - 1]).focus();
      }
    });
    document.addEventListener("click", function (e) {
      if (!form.contains(e.target)) close();
    });
  });

  // Full results page: /search/?q=...
  var page = document.getElementById("search-page-results");
  if (page) {
    var input = document.querySelector("form.search input");
    var renderPage = function () {
      var q = input ? input.value.trim() : "";
      page.textContent = "";
      if (!q) {
        page.appendChild(el("p", "secondary", "Type to search reps, bodies, laws, issues, the Constitution, and meetings."));
        return;
      }
      var results = search(q);
      if (!results.length) {
        page.appendChild(el("p", "secondary", "No matches for “" + q + "” in the sample data."));
        return;
      }
      var groups = {};
      var order = [];
      results.forEach(function (item) {
        if (!groups[item.type]) { groups[item.type] = []; order.push(item.type); }
        groups[item.type].push(item);
      });
      order.forEach(function (type) {
        var section = el("section", "card stack-sm");
        section.appendChild(el("h2", "label", type));
        groups[type].forEach(function (item) { section.appendChild(resultLink(item)); });
        page.appendChild(section);
      });
    };
    if (input) {
      input.value = new URLSearchParams(location.search).get("q") || "";
      input.addEventListener("input", function () {
        history.replaceState(null, "", input.value.trim() ? searchUrl(input.value.trim()) : "/search/");
        renderPage();
      });
    }
    renderPage();
  }

  // Scope filter (/issues/).
  document.querySelectorAll('input[name="scope"]').forEach(function (radio) {
    radio.addEventListener("change", function () {
      document.querySelectorAll("main [data-level]").forEach(function (item) {
        item.hidden = radio.value !== "all" && item.dataset.level !== radio.value;
      });
    });
  });

  // Tabs (rep profile). Without JS every panel shows and the tab links jump to them.
  document.querySelectorAll("[data-tabs]").forEach(function (root) {
    var tabs = Array.prototype.slice.call(root.querySelectorAll('[role="tab"]'));
    var ids = tabs.map(function (t) { return t.getAttribute("aria-controls"); });

    function show(id, focus) {
      tabs.forEach(function (t) {
        var on = t.getAttribute("aria-controls") === id;
        t.setAttribute("aria-selected", on ? "true" : "false");
        t.tabIndex = on ? 0 : -1;
        document.getElementById(t.getAttribute("aria-controls")).hidden = !on;
        if (on && focus) t.focus();
      });
    }

    tabs.forEach(function (t, i) {
      t.addEventListener("click", function (e) {
        e.preventDefault();
        var id = t.getAttribute("aria-controls");
        history.replaceState(null, "", "#" + id);
        show(id);
      });
      t.addEventListener("keydown", function (e) {
        var next = e.key === "ArrowRight" ? i + 1 : e.key === "ArrowLeft" ? i - 1 : null;
        if (next === null) return;
        e.preventDefault();
        show(ids[(next + ids.length) % ids.length], true);
      });
    });

    function fromHash() {
      var id = location.hash.slice(1);
      show(ids.indexOf(id) !== -1 ? id : ids[0]);
    }
    window.addEventListener("hashchange", fromHash);
    fromHash();
  });
})();
